export interface PanelState { mode: "compact" | "expanded"; busy: boolean }
export interface BinRecord { code: string; label: string; enabled: boolean }
export interface WarehouseState { panel: PanelState; bins: readonly BinRecord[] }

export type WarehouseCommand =
  | { type: "SET_MODE"; mode: PanelState["mode"] }
  | { type: "FLIP_BUSY" }
  | { type: "REGISTER_BIN"; bin: BinRecord }
  | { type: "FLIP_BIN"; code: string };

export const initialWarehouseState: WarehouseState = Object.freeze({
  panel: Object.freeze({ mode: "compact", busy: false }),
  bins: Object.freeze([] as BinRecord[]),
});

export function reduceWarehouse(state: WarehouseState, command: WarehouseCommand): WarehouseState {
  switch (command.type) {
    case "SET_MODE":
      return { panel: { ...state.panel, mode: command.mode }, bins: state.bins };
    case "FLIP_BUSY":
      return { panel: { ...state.panel, busy: !state.panel.busy }, bins: state.bins };
    case "REGISTER_BIN": {
      if (!command.bin.code.trim() || !command.bin.label.trim()) throw new TypeError("code and label must be nonblank");
      if (state.bins.some(bin => bin.code === command.bin.code)) throw new Error("duplicate bin code");
      return { panel: state.panel, bins: [...state.bins, command.bin] };
    }
    case "FLIP_BIN": {
      const index = state.bins.findIndex(bin => bin.code === command.code);
      if (index < 0) throw new Error("unknown bin code");
      return { panel: state.panel, bins: state.bins.map((bin, i) => i === index ? { ...bin, enabled: !bin.enabled } : bin) };
    }
  }
}

