import { initialWarehouseState, reduceWarehouse } from './solution';
import type { WarehouseState, BinRecord } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(fn: () => unknown, ctor: Function, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof (ctor as any)) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

equal(initialWarehouseState.panel.mode, 'compact', 'initial mode');
equal(initialWarehouseState.panel.busy, false, 'initial busy');
equal(initialWarehouseState.bins.length, 0, 'initial bins');

const modeState = reduceWarehouse(initialWarehouseState, { type: 'SET_MODE', mode: 'expanded' });
equal(modeState.panel.mode, 'expanded', 'mode changed');
assert(modeState !== initialWarehouseState, 'mode gets new root');
assert(modeState.panel !== initialWarehouseState.panel, 'mode gets new panel');
assert(modeState.bins === initialWarehouseState.bins, 'unchanged bins may be retained');
const sameMode = reduceWarehouse(modeState, { type: 'SET_MODE', mode: 'expanded' });
assert(sameMode !== modeState && sameMode.panel !== modeState.panel, 'successful same-value mode still creates required objects');

const busyState = reduceWarehouse(modeState, { type: 'FLIP_BUSY' });
equal(busyState.panel.busy, true, 'busy flipped');
assert(busyState !== modeState && busyState.panel !== modeState.panel, 'busy gets new root and panel');

const payload: BinRecord = { code: 'A1', label: 'Alpha', enabled: false };
const registered = reduceWarehouse(busyState, { type: 'REGISTER_BIN', bin: payload });
assert(registered !== busyState, 'register gets new root');
assert(registered.bins !== busyState.bins, 'register gets new bins array');
assert(registered.panel === busyState.panel, 'register retains unchanged panel');
assert(registered.bins[0] !== payload, 'registered bin copied');
(payload as { code: string; label: string; enabled: boolean }).label = 'mutated';
equal(registered.bins[0].label, 'Alpha', 'payload mutation isolated');

const second = reduceWarehouse(registered, { type: 'REGISTER_BIN', bin: { code: 'B2', label: 'Beta', enabled: true } });
equal(second.bins[0].code, 'A1', 'registration order first');
equal(second.bins[1].code, 'B2', 'registration order second');
const firstBefore = second.bins[0];
const secondBefore = second.bins[1];
const flipped = reduceWarehouse(second, { type: 'FLIP_BIN', code: 'A1' });
equal(flipped.bins[0].enabled, true, 'bin flipped');
assert(flipped.bins[0] !== firstBefore, 'flipped record copied');
assert(flipped.bins[1] === secondBefore, 'unchanged record identity retained');
equal(second.bins[0].enabled, false, 'prior state not mutated');

for (const bin of [{ code: '', label: 'x', enabled: true }, { code: '  ', label: 'x', enabled: true }, { code: 'x', label: '\t', enabled: true }]) {
  throws(() => reduceWarehouse(second, { type: 'REGISTER_BIN', bin }), TypeError, 'blank registration field');
}
throws(() => reduceWarehouse(second, { type: 'REGISTER_BIN', bin: { code: 'A1', label: 'again', enabled: true } }), Error, 'duplicate code');
const binsBeforeMissing = second.bins;
throws(() => reduceWarehouse(second, { type: 'FLIP_BIN', code: 'missing' }), Error, 'missing flip');
assert(second.bins === binsBeforeMissing && second.bins[0] === firstBefore, 'failed flip changes nothing');

const duplicateFirst = { code: 'D', label: 'first', enabled: false };
const duplicateSecond = { code: 'D', label: 'second', enabled: false };
const external: WarehouseState = { panel: { mode: 'compact', busy: false }, bins: [duplicateFirst, duplicateSecond] };
const duplicateFlip = reduceWarehouse(external, { type: 'FLIP_BIN', code: 'D' });
equal(duplicateFlip.bins[0].enabled, true, 'first duplicate flipped');
equal(duplicateFlip.bins[1].enabled, false, 'second duplicate unchanged');
assert(duplicateFlip.bins[1] === duplicateSecond, 'second duplicate identity retained');

